-- #144 판정 오류 사건과 공개 정정 기록 (ADR-0165; owner answers 144-3, 144-4, 144-5, 144-8,
-- 144-13, 144-14; ADR-0093 decision 1 #173 items 8, 13 and 15). Generated by `drizzle-kit
-- generate`, then hand-edited where marked: this header and the tail. The snapshot is as
-- generated. Additive: a table and its guards, and triggers on approval_requests that fire only
-- for the new kind; no existing row changes, so no reset (docs/RESET.md).
--
-- - market_judgement_incidents: one row per market whose paid result another admin confirmed
--   wrong (UNIQUE market_id, 144-14), written in the transaction that approves its
--   `market_judgement_incident` request at the decision's instant: the paid version and result
--   (FK to market_judgements), the corrected result (never the paid one), what went wrong (the
--   request's reason) with its evidence links (1-5) and collection instant, the request, its
--   registrant and instant, the confirmer and instant, the paid version's registrant (never the
--   confirmer, 144-4) and the transaction that wrote it. The market row, its judgements and its
--   settlement records never move (ADR-0165 decision 2): readers show the corrected result
--   beside the paid one. Permanent facts (N04 §5): buddha_app may INSERT and SELECT only, and a
--   trigger refuses an UPDATE or a DELETE whoever writes.
CREATE TABLE "market_judgement_incidents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"market_id" uuid NOT NULL,
	"applied_txid" text NOT NULL,
	"judgement_version" integer NOT NULL,
	"original_result" "market_result" NOT NULL,
	"corrected_result" "market_result" NOT NULL,
	"description" text NOT NULL,
	"evidence_links" text[] NOT NULL,
	"evidence_collected_at" timestamp (3) with time zone NOT NULL,
	"approval_id" uuid NOT NULL,
	"registered_by" text NOT NULL,
	"paid_registered_by" text NOT NULL,
	"confirmed_by" text NOT NULL,
	"registered_at" timestamp (3) with time zone NOT NULL,
	"confirmed_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "market_judgement_incidents_approval_id_unique" UNIQUE("approval_id"),
	CONSTRAINT "market_judgement_incidents_market_id_unique" UNIQUE("market_id"),
	CONSTRAINT "market_judgement_incidents_result_check" CHECK ("market_judgement_incidents"."corrected_result" <> "market_judgement_incidents"."original_result" AND "market_judgement_incidents"."judgement_version" >= 1),
	CONSTRAINT "market_judgement_incidents_confirmer_check" CHECK ("market_judgement_incidents"."confirmed_by" <> "market_judgement_incidents"."registered_by" AND "market_judgement_incidents"."confirmed_by" <> "market_judgement_incidents"."paid_registered_by" AND "market_judgement_incidents"."confirmed_at" > "market_judgement_incidents"."registered_at"),
	CONSTRAINT "market_judgement_incidents_evidence_check" CHECK (array_ndims("market_judgement_incidents"."evidence_links") = 1 AND cardinality("market_judgement_incidents"."evidence_links") BETWEEN 1 AND 5 AND array_position("market_judgement_incidents"."evidence_links", NULL) IS NULL AND "market_judgement_incidents"."evidence_collected_at" <= "market_judgement_incidents"."registered_at" AND btrim("market_judgement_incidents"."description") <> '' AND char_length("market_judgement_incidents"."description") <= 500)
);
