-- Hand-edited: an incident is a permanent fact, whoever writes; buddha_app keeps SELECT/INSERT of
-- the default privileges in docker/postgres/init/01-roles.sql and loses UPDATE and DELETE.
-- Emptying the table (the reset, wipe.ts) fires no row trigger.
REVOKE UPDATE, DELETE ON TABLE "market_judgement_incidents" FROM buddha_app;--> statement-breakpoint
CREATE FUNCTION market_judgement_incidents_keep_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  RAISE EXCEPTION 'judgement incident % is a permanent record and takes no %', OLD.id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_judgement_incidents_keep_record
  BEFORE UPDATE OR DELETE ON "market_judgement_incidents"
  FOR EACH ROW EXECUTE FUNCTION market_judgement_incidents_keep_record();--> statement-breakpoint
-- Hand-edited: a row is its approved request's, on its paid market, whoever writes (the pattern of
-- 0065's reconciliation_recoveries_check):
-- - written by the transaction that confirms it (`applied_txid`, as 0070's recall rows);
-- - the market is SETTLED (144-13: 오류 확인 once paid; a registration may come earlier, a
--   confirmation never does), and the row names its current judgement version, its result as the
--   original and that version's registrant (`paid_registered_by`) — the paid version stays the
--   current one, as nothing moves the market row after the payout;
-- - the request is an approved `market_judgement_incident` of this market, its requester and
--   requested_at the row's registrant and registered_at, its decider and decided_at the row's
--   confirmer and confirmed_at (the decision's one instant, ADR-0165), its reason the description,
--   and its frozen payload the version, the two results and the evidence of the row.
-- No admin-role check on either admin, as market_judgements has none: the decider's role is the
-- approval engine's under the shared admin-roles lock, and a registrant who lost the role since
-- would otherwise turn a confirmation into an integrity error. Runs as the invoker: buddha_app may
-- SELECT every table read; the search path is fixed with pg_temp last (0034, 0060).
CREATE FUNCTION market_judgement_incidents_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  m markets%ROWTYPE;
  paid market_judgements%ROWTYPE;
  approval approval_requests%ROWTYPE;
  evidence jsonb;
BEGIN
  IF NEW.applied_txid IS DISTINCT FROM pg_current_xact_id()::text THEN
    RAISE EXCEPTION 'judgement incident % is written by the transaction that confirms it', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT * INTO m FROM markets WHERE id = NEW.market_id;
  IF m.id IS NULL OR m.status::text <> 'settled' THEN
    RAISE EXCEPTION 'judgement incident % is confirmed on a settled market alone', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT * INTO paid FROM market_judgements
    WHERE market_id = NEW.market_id AND version = NEW.judgement_version;
  IF m.judgement_version IS DISTINCT FROM NEW.judgement_version
    OR m.resolved_result IS DISTINCT FROM NEW.original_result
    OR paid.registered_by IS DISTINCT FROM NEW.paid_registered_by THEN
    RAISE EXCEPTION 'judgement incident % names the market''s paid version, its result and its registrant', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT * INTO approval FROM approval_requests WHERE id = NEW.approval_id;
  IF approval.id IS NULL OR approval.kind <> 'market_judgement_incident'
    OR approval.status::text <> 'approved'
    OR approval.target_type IS DISTINCT FROM 'market'
    OR approval.target_id IS DISTINCT FROM NEW.market_id::text
    OR approval.requested_by IS DISTINCT FROM NEW.registered_by
    OR approval.requested_at IS DISTINCT FROM NEW.registered_at
    OR approval.decided_by IS DISTINCT FROM NEW.confirmed_by
    OR approval.decided_at IS DISTINCT FROM NEW.confirmed_at
    OR approval.request_reason IS DISTINCT FROM NEW.description THEN
    RAISE EXCEPTION 'judgement incident % needs its approved market_judgement_incident request', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  evidence := approval.payload -> 'evidence';
  IF jsonb_typeof(evidence -> 'links') IS DISTINCT FROM 'array'
    OR jsonb_typeof(evidence -> 'collectedAt') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'judgement incident % is the registration its request froze', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF approval.payload ->> 'judgementVersion' IS DISTINCT FROM NEW.judgement_version::text
    OR approval.payload ->> 'originalResult' IS DISTINCT FROM NEW.original_result::text
    OR approval.payload ->> 'correctedResult' IS DISTINCT FROM NEW.corrected_result::text
    OR ARRAY(SELECT jsonb_array_elements_text(evidence -> 'links')) IS DISTINCT FROM NEW.evidence_links
    OR (evidence ->> 'collectedAt')::timestamp (3) with time zone
      IS DISTINCT FROM NEW.evidence_collected_at THEN
    RAISE EXCEPTION 'judgement incident % is the registration its request froze', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_judgement_incidents_check
  BEFORE INSERT ON "market_judgement_incidents"
  FOR EACH ROW EXECUTE FUNCTION market_judgement_incidents_check();--> statement-breakpoint
-- Hand-edited: 144-4 where no row is written too — the paid version's registrant (the
-- market_judgements row at the market's current version) never decides an incident of the market,
-- neither 오류 확인 nor 기각 (the review 144-4 bars; a dismissal writes no incident row for the
-- CHECK above to refuse). The requester is approval_requests_decider_not_requester_check's. A
-- closure's rejection by no one (#140, decided_by NULL) passes. Compared as text and varchar, so
-- no enum value of this batch is named.
CREATE FUNCTION approval_requests_incident_registrant() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.decided_by IS NOT NULL AND NEW.target_type = 'market' THEN
    IF EXISTS (
      SELECT 1 FROM markets m
      JOIN market_judgements j ON j.market_id = m.id AND j.version = m.judgement_version
      WHERE m.id = NEW.target_id::uuid AND j.registered_by = NEW.decided_by
    ) THEN
      RAISE EXCEPTION 'the paid judgement version''s registrant does not decide judgement incident %', NEW.id
        USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER approval_requests_incident_registrant
  BEFORE UPDATE ON "approval_requests"
  FOR EACH ROW
  WHEN (NEW.kind = 'market_judgement_incident' AND OLD.status::text = 'pending'
    AND NEW.status::text IN ('approved', 'rejected'))
  EXECUTE FUNCTION approval_requests_incident_registrant();--> statement-breakpoint
-- Hand-edited: and an approved incident request commits only with its incident, written by the
-- deciding transaction — an approval without its record, or a record written later, is refused at
-- COMMIT (the deferred pattern of 0077's ledger_entries_regrant_record). With the BEFORE INSERT
-- trigger above, 오류 확인 and its permanent record are one fact.
CREATE FUNCTION approval_requests_incident_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM market_judgement_incidents i
    WHERE i.approval_id = NEW.id AND i.applied_txid = pg_current_xact_id()::text
  ) THEN
    RAISE EXCEPTION 'judgement incident request % is approved only with its incident, written by the same transaction', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER approval_requests_incident_record
  AFTER UPDATE ON "approval_requests"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (NEW.kind = 'market_judgement_incident' AND OLD.status::text = 'pending'
    AND NEW.status::text = 'approved')
  EXECUTE FUNCTION approval_requests_incident_record();
